import{_ as t,o,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/report3_spec.md","filePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/report3_spec.md"}'),l={name:"feature/agency-workspace/3-4-20-update-workspace-member-role/report3_spec.md"};function n(i,e,a,h,c,A){return o(),r("div",null,[...e[0]||(e[0]=[s("<p><strong>3.4.20 Update Workspace Member Role</strong></p><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace changes the role of one of its members.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the MANAGER adjust a member&#39;s role to match the work actually being done, including handing over the MANAGER role.</li><li><strong>Interface</strong>: A role selector in the member table, offering MANAGER, CREATOR, and CLIENT.</li><li><strong>Data Processing</strong>: The system loads the member, applies the single-MANAGER guards, updates the role, and returns the updated member.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Update Member Role Screen:</p><ul><li>The member table on the members screen.</li><li>A role selector per member with the values MANAGER, CREATOR, CLIENT.</li><li>A blocked state with a clear message when the change would leave the Workspace without a MANAGER or would create a second one.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the member identifier; the new role.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the member record and its current role; the count of active MANAGERs in the Workspace; the member&#39;s user record for building the response.</li><li><strong>Output</strong>: the updated member - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive, carrying the new role.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. Only MANAGER may change roles; any other caller -&gt; 403 FORBIDDEN. This runs before any service-level guard.</li><li><strong>BR-33</strong>: A role change affects the current Workspace only - it does not carry over to the same member&#39;s roles in other Workspaces of the Agency.</li><li><strong>BR-83</strong>: Last-MANAGER guard on demotion - if the member is the only active MANAGER of the Workspace and the new role is not MANAGER, the request is blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED; another MANAGER must be in place first. Checked before the duplicate-MANAGER guard.</li><li><strong>BR-87</strong>: Duplicate-MANAGER guard on promotion, checked second - if the new role is MANAGER and the member is not currently a MANAGER, the request is blocked with 409 MANAGER_ALREADY_ASSIGNED when the Workspace already has another active MANAGER.</li><li><strong>BR-29</strong>: The member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND.</li><li><strong>BR-31</strong>: The assignable workspace roles are MANAGER, CREATOR, CLIENT; there is no Workspace-level OWNER.</li><li><strong>BR-82</strong>: role must be one of the enum values; any other value is rejected.</li><li>There is no exception for changing one&#39;s own role - a MANAGER acting on themselves is subject to the same guards as any other member.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Toast <strong>MSG39</strong>.</li><li>role empty -&gt; Display: <strong>MSG02</strong>.</li><li>The member must exist, be active, and belong to that Workspace; otherwise 404 NOT_FOUND. Toast <strong>MSG38</strong>.</li><li>The new role must be one of MANAGER, CREATOR, CLIENT; otherwise Display: <strong>MSG95</strong>.</li><li>Demoting the only active MANAGER -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED. Toast <strong>MSG96</strong>.</li><li>Promoting to MANAGER while another active MANAGER exists -&gt; 409 MANAGER_ALREADY_ASSIGNED. Display: <strong>MSG95</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>MANAGER opens the members screen and picks a new role for a member in the role selector.</li><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li><li>System loads the member and checks that it exists, is active, and belongs to that Workspace; otherwise the request fails with 404 NOT_FOUND.</li><li>System applies the guards in order: the last-MANAGER guard when demoting the only active MANAGER, then the duplicate-MANAGER guard when promoting to MANAGER while another active MANAGER exists.</li><li>System stores the new role on the membership and returns the updated member.</li><li>Screen refreshes the role shown for that member.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 2.a2: The screen blocks the action.</li><li>3.a1: Member does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The screen refreshes the member list.</li><li>4.a1: Demoting the only active MANAGER to CREATOR or CLIENT -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG96</strong>. 4.a2: The MANAGER hands the MANAGER role to another member first, then retries.</li><li>4.b1: Promoting a member to MANAGER while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, Display: <strong>MSG95</strong>. 4.b2: The MANAGER demotes the current MANAGER first, or picks a different role.</li><li>A MANAGER demotes themselves -&gt; allowed when at least one other MANAGER remains; blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED when they are the only MANAGER.</li><li>A role change between CREATOR and CLIENT -&gt; always allowed.</li><li>Setting the role to the value it already holds -&gt; allowed; no guard blocks a no-op change.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The member holds the new role in this Workspace only.</li><li>The Workspace still has exactly one active MANAGER.</li></ul>",14)])])}const m=t(l,[["render",n]]);export{p as __pageData,m as default};
